// Liefert das Aggregat aus BC3-20, „Tickets und Audit bauen“ und „Lieferung prüfen“
// greifen per $('Umschlag auspacken') darauf zu.
const rein = $input.first().json;
const a = rein.umschlag?.aggregat;
if (!a) throw new Error('Kein Aggregat im Umschlag. Lief BC3-20 durch?');
return [{ json: a }];

// „Tickets und Audit bauen“ erwartet die Compliance-Antwort als $input.first().json.output.
const u = $('Vom Orchestrator aufgerufen').first().json.umschlag || {};
return [{ json: { output: u.compliance_roh ?? JSON.stringify(u.compliance || {}) } }];

// Tickets und Audit bauen: aus den Epics von BC3-20 und dem Befund von BC3-30
// entstehen tickets.json (Vertrag mit BC4) und compliance-audit.json.
// Die IDs vergibt dieser Baustein, nicht das Sprachmodell: gleiches Konzept
// ergibt dieselben IDs, Läufe bleiben vergleichbar.
// Gibt zwei Items zurück: [0] tickets, [1] compliance-audit.

// ---------------------------------------------------------------- Eingaben
const complianceRaw = $input.first().json.output;
let cleaned = String(complianceRaw).trim();
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

let compliance = {};
let complianceFehler = null;
try {
  compliance = JSON.parse(cleaned);
} catch (e) {
  complianceFehler = e.message;
  compliance = {};
}

const aggregate = $('Umschlag auspacken').first().json;

// Vertragsversion: '3.5' mit Prozess- und Teilprozesskennung (Auflage BC0), '3.4' ohne
const TICKETS_SCHEMA_VERSION = '3.5';
const MIT_KENNUNG = TICKETS_SCHEMA_VERSION === '3.5';


// ---------------------------------------------------------------- Helfer

/** Deterministische Hex-Kette aus einem Text (FNV-1a, mehrfach gefaltet). */
function hexAus(text, laenge) {
  let out = '';
  for (let runde = 0; out.length < laenge; runde++) {
    let x = 2166136261 ^ runde;
    const s = String(text) + '#' + runde;
    for (let i = 0; i < s.length; i++) {
      x ^= s.charCodeAt(i);
      x = Math.imul(x, 16777619);
    }
    out += (x >>> 0).toString(16).padStart(8, '0');
  }
  return out.slice(0, laenge);
}

/** 24 Hex-Zeichen, aufgeteilt als 4-4-4-12. */
function idBlock(saat) {
  const h = hexAus(saat, 24);
  return `${h.slice(0, 4)}-${h.slice(4, 8)}-${h.slice(8, 12)}-${h.slice(12, 24)}`;
}

/** Auf ^[a-z0-9-]{2,30}$ bringen. */
function kurzname(text) {
  let s = String(text || '')
    .toLowerCase()
    .replace(/[äàáâ]/g, 'a').replace(/[öòóô]/g, 'o').replace(/[üùúû]/g, 'u')
    .replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 30)
    .replace(/-+$/g, '');
  if (s.length < 2) s = 'lieferung';
  return s;
}

// ---------------------------------------------------------------- Aufbau

const basis = String(aggregate.original_filename || 'lieferung').replace(/\.[^.]+$/, '');
const projekt = kurzname(basis.replace(/^mock[-_]?/, '').replace(/^konzept[-_]?/, ''));

// Zuordnung Epic -> Use Case, nur für das Compliance-Audit
const zuordnung = [];

// Alte Story-ID des Modells -> neue ID, je Epic eine Karte: das Modell vergibt
// in jedem Epic dieselben schlichten IDs (ep-1-1, ep-1-2 ...)
const idKarten = [];

// ------------------------------------------------- Compliance-Stories zuordnen
//
// Vor dem Aufbau, weil nur eindeutige Zuordnungen gelten. use_case_id_ref
// schlägt epic_id_ref ("ep-1" passt auf alle Epics). Mehrdeutiges wird
// gemeldet, nicht geraten.
const epicListe = aggregate.epics || [];

/** Pflicht-IDs einer Zusatz-Story als Liste ("p4" oder "p2,p5"). */
function pflichtIds(zs) {
  return String(zs.begruendung_pflicht_id || '')
    .split(/[,;\s]+/)
    .map(s => s.trim())
    .filter(Boolean);
}

// BC3-30 nennt manchmal eine Story statt des Epics (ep-288edb94-3): auf das
// Epic kürzen, bei nur einem Epic dorthin
const korrigiert = [];
function trefferFuer(wert) {
  if (!wert) return [];
  const treffer = [];
  epicListe.forEach((e, i) => {
    if (e.use_case_id_ref === wert || e.epic_id === wert) treffer.push(i);
  });
  if (treffer.length) return treffer;
  const gekuerzt = String(wert).replace(/-\d+$/, '');
  epicListe.forEach((e, i) => { if (gekuerzt !== wert && e.epic_id === gekuerzt) treffer.push(i); });
  if (treffer.length) {
    korrigiert.push({ verweis: wert, epic_id: gekuerzt });
    return treffer;
  }
  return [];
}

// Dublettenbremse: Ähnlichkeit = Anteil gemeinsamer Wortstämme ohne Füllwörter.
// Schwelle 0,4 (Doppel lagen bei 0,42 bis 0,70, andere höchstens bei 0,25)
const AEHNLICH_AB = 0.4;
const FUELLWOERTER = new Set(('given when then eine einer einem einen ein der die das den dem des und oder ist sind '
  + 'wird werden nur mit von zu im in am an auf aus bei für fuer sie er es dies diese dieser als nicht kein keine '
  + 'so dass wenn').split(' '));
function staemme(text) {
  const flach = String(text || '').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');
  return new Set(flach.split(/[^a-z0-9]+/).filter(w => w.length > 2 && !FUELLWOERTER.has(w)).map(w => w.slice(0, 6)));
}
function aehnlichkeit(a, b) {
  const A = staemme(a), B = staemme(b);
  const gemeinsam = [...A].filter(x => B.has(x)).length;
  return gemeinsam / ((A.size + B.size - gemeinsam) || 1);
}
const zusammengelegt = [];

// abgedeckt_durch aus BC3-30: vorhandene Story, die eine Pflicht schon erfüllt.
// Gilt nur für existierende Kennungen, dann keine Zusatz-Story
const vorhandeneIds = new Set(epicListe.flatMap(e => (e.stories || []).map(s => String(s.story_id))));
const abgedecktDurch = new Map();   // Pflicht-ID -> [alte Story-IDs]
const verweisUngueltig = [];
for (const p of compliance.pflichten || []) {
  const ids = (Array.isArray(p.abgedeckt_durch) ? p.abgedeckt_durch : [p.abgedeckt_durch])
    .filter(x => x && !/^</.test(String(x))).map(String);
  if (!ids.length || (p.adressat || 'bc4') !== 'bc4') continue;
  const gut = ids.filter(id => vorhandeneIds.has(id));
  ids.filter(id => !vorhandeneIds.has(id)).forEach(id => verweisUngueltig.push({ pflicht_id: p.id, verweis: id }));
  if (gut.length) abgedecktDurch.set(p.id, gut);
}

const zusatzProEpic = new Map();   // epicIndex -> [zusatzStory]
const nichtZugeordnet = [];
const nichtAnBc4 = [];

// Nur was BC4 bauen kann, wird ein Ticket. Organisatorische Pflichten (Mensch,
// Frist) bleiben im Audit. Fehlt der Adressat, gilt 'bc4' mit Befund
const adressatVon = new Map((compliance.pflichten || []).map(p => [p.id, p.adressat || null]));
let ohneAdressat = 0;

function darfAnBc4(ids) {
  if (!ids.length) return true;               // ohne Bezug nicht blockieren
  const arten = ids.map(id => {
    const a = adressatVon.get(id);
    if (!a) ohneAdressat++;
    return a || 'bc4';
  });
  return arten.includes('bc4');
}

for (const zs of compliance.empfohlene_zusatz_stories || []) {
  const ids = pflichtIds(zs);
  if (!darfAnBc4(ids)) {
    nichtAnBc4.push({
      titel: String(zs.titel || ''),
      pflicht_ids: ids,
      adressaten: [...new Set(ids.map(i => adressatVon.get(i) || 'bc4'))],
      grund: 'Diese Pflicht kann BC4 nicht bauen. Sie steht als Pflicht im Audit.',
    });
    continue;
  }
  let treffer = trefferFuer(zs.use_case_id_ref);
  let quelle = 'use_case_id_ref';
  if (treffer.length !== 1) {
    treffer = trefferFuer(zs.epic_id_ref);
    quelle = 'epic_id_ref';
  }
  if (!treffer.length && epicListe.length === 1) {
    korrigiert.push({ verweis: zs.epic_id_ref || zs.use_case_id_ref || 'ohne Angabe', epic_id: epicListe[0].epic_id });
    treffer = [0];
  }

  if (treffer.length === 1) {
    const i = treffer[0];
    if (!zusatzProEpic.has(i)) zusatzProEpic.set(i, []);
    zusatzProEpic.get(i).push(zs);
  } else {
    nichtZugeordnet.push({
      titel: String(zs.titel || ''),
      epic_id_ref: zs.epic_id_ref || null,
      use_case_id_ref: zs.use_case_id_ref || null,
      pflicht_ids: pflichtIds(zs),
      grund: treffer.length > 1
        ? `mehrdeutig - ${quelle} passt auf ${treffer.length} Epics`
        : 'kein passendes Epic gefunden',
    });
  }
}

const epics = epicListe.map((epic, i) => {
  // Saat: älteste potenzial_id (id_saat), damit ein Nachfolger dieselbe
  // Epic-ID bekommt wie sein Vorgänger (#242)
  const saat = epic.id_saat
    ? `potenzial|${epic.id_saat}`
    : `${aggregate.konzept_id}|${epic.use_case_id_ref || epic.epic_id || i}`;
  const block = idBlock(saat);
  const epicId = `ep-${block}`;

  zuordnung.push({
    epic_id: epicId,
    use_case_id_ref: epic.use_case_id_ref || null,
    id_saat: epic.id_saat || null,
    titel: epic.titel,
  });

  // Fachliche Stories aus BC3-20
  const idKarte = new Map();
  idKarten.push(idKarte);
  const fachlich = (epic.stories || []).map((s, n) => {
    const neueId = `st-${block}-${n + 1}`;
    if (s.story_id) idKarte.set(String(s.story_id), neueId);
    return {
      story_id: neueId,
      titel: String(s.titel || ''),
      beschreibung: String(s.beschreibung || ''),
      akzeptanzkriterien: Array.isArray(s.akzeptanzkriterien) ? s.akzeptanzkriterien : [],
      // roh, wird unten auf die neuen IDs umgeschrieben
      abhaengigkeiten: Array.isArray(s.abhaengigkeiten) ? s.abhaengigkeiten : [],
    };
  });

  // Compliance-Stories anhängen, außer ihre Pflicht oder ihre Kriterien stehen
  // schon in einer Story dieses Epics
  const vorhanden = fachlich.flatMap(s => s.akzeptanzkriterien.map(k => ({ story_id: s.story_id, titel: s.titel, text: k.text || '' })));
  const zusatzRoh = [];
  for (const zs of zusatzProEpic.get(i) || []) {
    const pids = pflichtIds(zs);
    if (pids.length && pids.every(id => abgedecktDurch.has(id))) {
      zusammengelegt.push({
        titel: String(zs.titel || ''),
        pflicht_ids: pids,
        steht_schon_in: [...new Set(pids.flatMap(id => abgedecktDurch.get(id)))].map(alt => {
          const s = (epic.stories || []).find(x => String(x.story_id) === alt);
          return { story_id: idKarte.get(alt) || alt, titel: s ? String(s.titel || '') : alt };
        }),
        quelle: 'abgedeckt_durch',
      });
      continue;
    }
    const kriterien = Array.isArray(zs.akzeptanzkriterien) ? zs.akzeptanzkriterien : [];
    const gleich = kriterien.map(k => {
      let best = null;
      for (const v of vorhanden) {
        const a = aehnlichkeit(k.text, v.text);
        if (a >= AEHNLICH_AB && (!best || a > best.a)) best = { ...v, a };
      }
      return best;
    });
    if (kriterien.length && gleich.every(Boolean)) {
      const stories = [...new Map(gleich.map(g => [g.story_id, g.titel])).entries()];
      zusammengelegt.push({
        titel: String(zs.titel || ''),
        pflicht_ids: pflichtIds(zs),
        steht_schon_in: stories.map(([story_id, titel]) => ({ story_id, titel })),
        aehnlichkeit: gleich.map(g => Math.round(g.a * 100) / 100),
      });
      for (const [story_id] of stories) zuordnung.push({ story_id, herkunft: 'fachlich mit Pflicht', pflicht_ids: pflichtIds(zs) });
      continue;
    }
    const neueId = `st-${block}-${fachlich.length + zusatzRoh.length + 1}`;
    for (const k of kriterien) vorhanden.push({ story_id: neueId, titel: String(zs.titel || ''), text: k.text || '' });
    zusatzRoh.push(zs);
  }

  const zusatz = zusatzRoh.map((zs, n) => ({
    story_id: `st-${block}-${fachlich.length + n + 1}`,
    titel: String(zs.titel || ''),
    beschreibung: String(zs.beschreibung || ''),
    akzeptanzkriterien: Array.isArray(zs.akzeptanzkriterien) ? zs.akzeptanzkriterien : [],
    abhaengigkeiten: [],
  }));

  // Herkunft der Compliance-Stories für das Audit festhalten
  zusatzRoh.forEach((zs, n) => {
    zuordnung.push({
      story_id: `st-${block}-${fachlich.length + n + 1}`,
      herkunft: 'compliance',
      pflicht_ids: pflichtIds(zs),
    });
  });

  const gebaut = {
    epic_id: epicId,
    titel: String(epic.titel || ''),
    ziel: String(epic.ziel || ''),
    kategorien: Array.isArray(epic.kategorien) ? epic.kategorien : [],
    stories: [...fachlich, ...zusatz],
  };

  // Teilprozesskennung nur in 3.5
  if (MIT_KENNUNG && Array.isArray(epic.teilprozess_ids) && epic.teilprozess_ids.length) {
    gebaut.teilprozess_ids = epic.teilprozess_ids;
  }

  return gebaut;
});

// Abhängigkeiten auf die neuen IDs umschreiben, unauflösbare fallen weg
let verworfeneVerweise = 0;
epics.forEach((epic, i) => {
  const idKarte = idKarten[i] || new Map();
  for (const s of epic.stories) {
    const umgeschrieben = [];
    for (const alt of s.abhaengigkeiten) {
      const neu = idKarte.get(String(alt));
      if (neu && neu !== s.story_id) umgeschrieben.push(neu);
      else verworfeneVerweise++;
    }
    s.abhaengigkeiten = [...new Set(umgeschrieben)];
  }
});

// Abgleich Pflichten <-> Stories. Fehlende Compliance-Stories nur melden,
// nicht erfinden
const abgedeckt = new Set();
// Pflichten, die BC3-30 über abgedeckt_durch einer vorhandenen Story zuordnet
for (const [pid, alte] of abgedecktDurch) {
  for (const alt of alte) {
    const i = idKarten.findIndex(k => k.has(alt));
    if (i >= 0) zuordnung.push({ story_id: idKarten[i].get(alt), herkunft: 'fachlich mit Pflicht', pflicht_ids: [pid], quelle: 'abgedeckt_durch' });
  }
}
for (const z of zuordnung) {
  if (z.herkunft === 'compliance' || z.herkunft === 'fachlich mit Pflicht') for (const id of z.pflicht_ids || []) abgedeckt.add(id);
}

// Nur Pflichten, die BC4 bauen kann
const pflichtenOhneStory = (compliance.pflichten || [])
  .filter(p => p.wird_zu_story === true && (p.adressat || 'bc4') === 'bc4'
               && !abgedeckt.has(p.id))
  .map(p => ({
    id: p.id || null,
    tag: p.tag || null,
    text: String(p.text || ''),
    owner: p.owner || null,
  }));

const storiesOhnePflichtvermerk = (compliance.pflichten || [])
  .filter(p => p.wird_zu_story !== true && abgedeckt.has(p.id))
  .map(p => p.id);

// Kennung mit Sekunden, einmal berechnet, reist im Umschlag mit
const jetzt = new Date().toISOString();
const lieferungId = `del-${projekt}-${jetzt.slice(0, 10)}-${jetzt.slice(11, 19).replace(/:/g, '')}`;


// source_file ist Pflicht im Vertrag
const konzeptRef = {
  konzept_id: aggregate.konzept_id,
  schema_version: aggregate.schema_version,
  source_file: aggregate.original_filename,
};
if (MIT_KENNUNG) {
  konzeptRef.kp_id = aggregate.kp_id;
  if ((aggregate.teilprozess_ids || []).length) {
    konzeptRef.teilprozess_ids = aggregate.teilprozess_ids;
  }
  if (aggregate.value_quelle) {
    konzeptRef.value_quelle = aggregate.value_quelle;
  }
}

// --- Datei 1: tickets.json (nur die im Vertrag erlaubten Felder) ----------
const tickets = {
  lieferung_id: lieferungId,
  schema_version: TICKETS_SCHEMA_VERSION,
  projekt_kurzname: projekt,
  konzept_ref: konzeptRef,
  epics: epics,
  gate2: { status: 'pending' },
};


// --- Datei 2: compliance-audit.json ---------------------------------------
const complianceAudit = {
  lieferung_id: lieferungId,
  schema_version: TICKETS_SCHEMA_VERSION,
  projekt_kurzname: projekt,
  erzeugt_am: new Date().toISOString(),
  konzept_ref: tickets.konzept_ref,
  prozess_kurzbeschreibung: aggregate.prozess,
  vorpruefung: {
    ampel: compliance.ampel ?? null,
    ai_act_klasse: compliance.ai_act_klasse ?? null,
    anhang_iii_kategorie: compliance.anhang_iii_kategorie ?? null,
    dsgvo_rechtsgrundlage: compliance.dsgvo_rechtsgrundlage ?? null,
    betroffene_datenarten: compliance.betroffene_datenarten ?? [],
    begruendung_ampel: compliance.begruendung_ampel ?? null,
  },
  pflichten: compliance.pflichten ?? [],
  // Nach Adressat sortiert, BC4 baut nur die erste Gruppe
  pflichten_nach_adressat: (() => {
    const g = { bc4: [], organisation: [], plattform: [], ohne_angabe: [] };
    for (const p of compliance.pflichten || []) {
      const a = p.adressat;
      (g[a] || g[a === undefined || a === null ? 'ohne_angabe' : 'bc4']).push(p.id);
    }
    return g;
  })(),
  nicht_an_bc4: nichtAnBc4,
  plattform_standards: compliance.plattform_standards ?? [],
  zuordnung: zuordnung,
  nicht_zugeordnete_compliance_stories: nichtZugeordnet,
  zuordnung_korrigiert: korrigiert,
  zusammengelegt: zusammengelegt,
  befunde_zuordnung: [
    // Jede Zuordnung aus abgedeckt_durch prüft ein Mensch an Gate 2, darum zuerst
    ...[...abgedecktDurch].map(([pid, alte]) => {
      const p = (compliance.pflichten || []).find(x => x.id === pid) || {};
      const titel = alte.map(alt => {
        const s = epicListe.flatMap(e => e.stories || []).find(x => String(x.story_id) === alt);
        return `„${String(s?.titel || alt).slice(0, 60)}“`;
      }).join(' und ');
      return `Prüfen: Pflicht ${pid} ${p.tag || ''} gilt laut BC3-30 durch ${titel} als erfüllt.`.replace(/\s+/g, ' ');
    }),
    ...verweisUngueltig.map(v => `Pflicht ${v.pflicht_id}: abgedeckt_durch nennt ${v.verweis}, diese Story gibt es nicht.`),
    ...korrigiert.map(k => `Compliance-Story verwies auf ${k.verweis}, dem Epic ${k.epic_id} zugeordnet.`),
    ...zusammengelegt.map(z => `Compliance-Story „${z.titel}“ nicht angehängt, `
      + (z.quelle === 'abgedeckt_durch' ? 'BC3-30 ordnet die Pflicht der vorhandenen Story ' : 'ihre Kriterien stehen schon in ')
      + z.steht_schon_in.map(s => `„${s.titel}“`).join(' und ') + (z.quelle === 'abgedeckt_durch' ? ' zu' : '') + ` (Pflicht ${z.pflicht_ids.join(', ') || 'ohne Angabe'}).`),
  ],
  // Pflichten, die laut BC3-30 eine Story brauchen, aber keine haben
  pflichten_ohne_story: pflichtenOhneStory,
  pflichten_mit_story_ohne_vermerk: storiesOhnePflichtvermerk,
  befunde_adressat: [
    ...(ohneAdressat
      ? [`${ohneAdressat} Verweise auf Pflichten ohne Angabe des Adressaten. ` +
         `Ersatzweise als 'bc4' behandelt - bitte im Compliance-Befund nachsehen.`]
      : []),
    ...(nichtAnBc4.length
      ? [`${nichtAnBc4.length} Compliance-Story nicht an BC4 geliefert, weil BC4 sie ` +
         `nicht bauen kann: ${nichtAnBc4.map(x => x.titel).join('; ')}`]
      : []),
  ],
  // Kein Feld dsb_freigabe: einen Datenschutzbeauftragten gibt es im Projekt nicht
};

// --- Kennzahlen für die Ausführungsansicht ------------------------------
const anzahlStories = epics.reduce((n, e) => n + e.stories.length, 0);
const anzahlCompliance = zuordnung.filter(z => z.herkunft === 'compliance').length;

return [
  {
    json: {
      _datei: 'tickets',
      ...tickets,
      _statistik: {
        anzahl_epics: epics.length,
        anzahl_stories: anzahlStories,
        davon_compliance: anzahlCompliance,
        ampel: compliance.ampel ?? null,
        compliance_parse_fehler: complianceFehler,
        verworfene_verweise: verworfeneVerweise,
        compliance_stories_ohne_epic: nichtZugeordnet.length,
        pflichten_ohne_story: pflichtenOhneStory.length,
        zusammengelegt: zusammengelegt.length,
      },
    },
  },
  {
    json: {
      _datei: 'compliance-audit',
      ...complianceAudit,
    },
  },
];

/**
 * Ausgangsprüfung, läuft vor dem Hochladen.
 *
 * Prüft die tickets.json gegen tickets.schema.json, von Hand nachgebaut,
 * weil ein Code-Baustein keine Schema-Bibliothek hat. Bricht ab, wenn etwas
 * nicht passt: lieber keine Lieferung als eine vertragswidrige.
 *
 * Geprüft wird gegen die Fassung, die in „Tickets und Audit bauen“ eingestellt ist.
 * Bei 3.4 sind kp_id und teilprozess_ids nicht erlaubt, bei 3.5 schon.
 */
const items = $input.all();
const tickets = items.find(i => i.json._datei === 'tickets')?.json;
const audit   = items.find(i => i.json._datei !== 'tickets')?.json;
const f = [];
const weich = [];

if (!tickets) throw new Error('Ausgangspruefung: keine tickets.json im Eingang gefunden.');

const V = String(tickets.schema_version || '');
const mitKennung = V === '3.5';

const ERLAUBT_OBEN = ['lieferung_id', 'schema_version', 'projekt_kurzname', 'konzept_ref', 'epics', 'gate2'];
const RE_LIEFERUNG = /^(del-[a-z0-9-]+|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/;
const RE_EPIC  = /^ep-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const RE_STORY = /^st-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-[0-9]+$/;
const RE_KAT   = /^(it|fin|gov|sec):[a-z0-9-]+$/;
const RE_KURZ  = /^[a-z0-9-]{2,30}$/;
const RE_KP    = /^KP-(0[1-9]|10)$/;
const RE_TP    = /^KP-(0[1-9]|10)\.TP-[1-9][0-9]?$/;

// --- oberste Ebene ---------------------------------------------------------
const oben = Object.keys(tickets).filter(k => !k.startsWith('_'));
oben.filter(k => !ERLAUBT_OBEN.includes(k))
    .forEach(k => f.push(`Oberste Ebene: "${k}" ist im Vertrag nicht vorgesehen (additionalProperties: false).`));
ERLAUBT_OBEN.filter(k => tickets[k] === undefined)
    .forEach(k => f.push(`Oberste Ebene: Pflichtfeld "${k}" fehlt.`));

if (!RE_LIEFERUNG.test(String(tickets.lieferung_id))) f.push(`lieferung_id "${tickets.lieferung_id}" passt nicht zum Muster.`);
if (!RE_KURZ.test(String(tickets.projekt_kurzname))) f.push(`projekt_kurzname "${tickets.projekt_kurzname}" passt nicht zu ^[a-z0-9-]{2,30}$.`);
if (!['3.4', '3.5'].includes(V)) f.push(`schema_version "${V}" ist weder 3.4 noch 3.5.`);

// --- konzept_ref -----------------------------------------------------------
const kr = tickets.konzept_ref || {};
['konzept_id', 'schema_version', 'source_file'].forEach(k => {
  if (!kr[k]) f.push(`konzept_ref: Pflichtfeld "${k}" fehlt.`);
});
if (mitKennung) {
  if (!kr.kp_id) f.push('konzept_ref: kp_id fehlt (in 3.5 Pflicht, Auflage BC0).');
  else if (!RE_KP.test(kr.kp_id)) f.push(`konzept_ref: kp_id "${kr.kp_id}" passt nicht zum Muster.`);
  (kr.teilprozess_ids || []).forEach(t => {
    if (!RE_TP.test(t)) f.push(`konzept_ref: Teilprozess "${t}" passt nicht zum Muster.`);
  });
} else {
  ['kp_id', 'teilprozess_ids', 'value_quelle'].forEach(k => {
    if (kr[k] !== undefined) f.push(`konzept_ref: "${k}" ist in 3.4 nicht erlaubt. Entweder Vertrag auf 3.5 heben oder Feld weglassen.`);
  });
}

// --- Epics und Stories -----------------------------------------------------
if (!Array.isArray(tickets.epics) || tickets.epics.length === 0) f.push('epics ist leer.');

const alleStoryIds = new Set();
(tickets.epics || []).forEach((e, i) => {
  const wo = `Epic ${i + 1}`;
  const erlaubt = mitKennung
    ? ['epic_id', 'titel', 'ziel', 'kategorien', 'stories', 'teilprozess_ids']
    : ['epic_id', 'titel', 'ziel', 'kategorien', 'stories'];
  Object.keys(e).filter(k => !erlaubt.includes(k))
        .forEach(k => f.push(`${wo}: Feld "${k}" ist nicht erlaubt.`));

  if (!RE_EPIC.test(String(e.epic_id))) f.push(`${wo}: epic_id "${e.epic_id}" passt nicht zum Muster.`);
  if (String(e.titel || '').length < 5 || String(e.titel || '').length > 150) f.push(`${wo}: titel muss 5 bis 150 Zeichen haben (ist ${String(e.titel || '').length}).`);
  if (String(e.ziel || '').length < 20 || String(e.ziel || '').length > 600) f.push(`${wo}: ziel muss 20 bis 600 Zeichen haben (ist ${String(e.ziel || '').length}).`);
  if (!(e.kategorien || []).length) f.push(`${wo}: kategorien ist leer.`);
  (e.kategorien || []).forEach(k => { if (!RE_KAT.test(k)) f.push(`${wo}: Kategorie "${k}" passt nicht zu it|fin|gov|sec:...`); });
  // BC0 verlangt die Kennung auf Prozess- ODER Teilprozessebene. kp_id steht
  // in konzept_ref und ist Pflicht; die Teilprozess-ID ist ein Zugewinn.
  if (mitKennung && !(e.teilprozess_ids || []).length) {
    weich.push(`${wo}: keine Teilprozess-Kennung. Die Zuordnung läuft nur über kp_id ${kr.kp_id || '?'}.`);
  }

  const st = e.stories || [];
  if (!st.length) f.push(`${wo}: keine Stories.`);
  st.forEach((s, j) => {
    const wos = `${wo}, Story ${j + 1}`;
    Object.keys(s).filter(k => !['story_id', 'titel', 'beschreibung', 'akzeptanzkriterien', 'abhaengigkeiten'].includes(k))
          .forEach(k => f.push(`${wos}: Feld "${k}" ist nicht erlaubt.`));
    if (!RE_STORY.test(String(s.story_id))) f.push(`${wos}: story_id "${s.story_id}" passt nicht zum Muster.`);
    else alleStoryIds.add(s.story_id);
    if (String(s.titel || '').length < 5 || String(s.titel || '').length > 150) f.push(`${wos}: titel muss 5 bis 150 Zeichen haben.`);
    const b = String(s.beschreibung || '');
    if (b.length < 20 || b.length > 1500) f.push(`${wos}: beschreibung muss 20 bis 1500 Zeichen haben (ist ${b.length}).`);
    const ak = s.akzeptanzkriterien || [];
    if (!ak.length) f.push(`${wos}: kein Akzeptanzkriterium.`);
    ak.forEach((k, n) => {
      if (String(k.text || '').length < 10) f.push(`${wos}, Kriterium ${n + 1}: text zu kurz.`);
      if (String(k.messverfahren || '').length < 5) f.push(`${wos}, Kriterium ${n + 1}: messverfahren fehlt oder zu kurz.`);
      Object.keys(k).filter(x => !['text', 'messverfahren'].includes(x))
            .forEach(x => f.push(`${wos}, Kriterium ${n + 1}: Feld "${x}" ist nicht erlaubt.`));
    });
    if (!Array.isArray(s.abhaengigkeiten)) f.push(`${wos}: abhaengigkeiten muss eine Liste sein.`);
  });
});

// Verweise müssen auf vorhandene Stories zeigen
(tickets.epics || []).forEach((e, i) => (e.stories || []).forEach((s, j) => {
  (s.abhaengigkeiten || []).forEach(v => {
    if (!RE_STORY.test(String(v))) f.push(`Epic ${i + 1}, Story ${j + 1}: Verweis "${v}" passt nicht zum Muster.`);
    else if (!alleStoryIds.has(v)) f.push(`Epic ${i + 1}, Story ${j + 1}: Verweis "${v}" zeigt ins Leere.`);
  });
}));

// --- gate2 -----------------------------------------------------------------
// 'nachbessern' seit dem 04.09.2026: Gate 2 hat drei Entscheidungen statt zwei.
// Ohne diesen Wert wirft die Ausgangspruefung beim Wiederholungslauf nach einer
// Nachbesserung - die dritte Entscheidung waere eine Falle gewesen.
if (!['pending', 'approved', 'rejected', 'nachbessern']
      .includes(String(tickets.gate2?.status))) {
  f.push(`gate2.status "${tickets.gate2?.status}" ist kein zulässiger Wert.`);
}

// --- Abschreibschutz (seit 12.10.2026) ------------------------------------
// Ozans Generator gibt das GANZE ticket_set als ORIGINALTICKET an sein
// Sprachmodell ('n8n-Workflow erzeugen' in wf_generator.json). Nennt es den
// handgebauten UC2-Prototyp, kann der Generator ihn nachbauen - und der
// Soll-Ist-Vergleich gegen genau diesen Prototyp beweist nichts mehr.
// Gesperrt sind nur volle Namen und Kennungen aus dem Prototyp (Stand GitHub
// main, 03.10.2026), keine Teilwoerter: 'Aurelia' und die AUR-Dokumente
// braucht ein erzeugter Workflow rechtmaessig.
const SPERRLISTE = [
  // Dateien
  'UC2_Indexierung_14_Dokumente', 'UC2_Fragenbeantwortung_14_Dokumente_v2_4',
  'UC2_TEST_Quellenkonflikt', 'manifest_abschluss', 'etappe1_sollantworten',
  'ABSCHLUSSTESTS.md', 'LOKALE_PAKETPRUEFUNG', 'bc4-autonomous-builder/examples/uc2-wissensbasis',
  // Workflow-Namen
  'UC2 Aurelia – GitHub Indexierung – 14 Dokumente',
  'UC2 Aurelia – Fragen mit Quellen – 14 Dokumente v2.4',
  'UC2 TEST – isolierter Quellenkonflikt',
  // Versionskennungen aus manifest_abschluss.json
  'uc2-qa-v2.4-14docs', 'uc2-prompt-v2.2', 'uc2_grounded_answer_v2_2', 'uc2-validator-v2.4',
  // Tabellen und Funktionen aus den SQL-Dateien 001-006
  'uc2_documents', 'uc2_chunks', 'uc2_query_runs', 'uc2_index_state',
  'uc2_replace_document', 'uc2_search', 'uc2_log_run',
];
const ticketText = JSON.stringify(tickets).toLowerCase();
const gesperrt = SPERRLISTE.filter(s => ticketText.includes(s.toLowerCase()));
if (gesperrt.length) {
  const satz = `Abschreibschutz: das Ticket-Set nennt den UC2-Prototyp von BC4 (${gesperrt.join(', ')}). `
    + `Der Generator saehe damit die Referenz, gegen die er gemessen wird.`;
  // Seit 22.10.2026 bei jedem Konzept ein harter Fehler, nicht nur bei KP-05
  f.push(satz + ' Den Verweis in BC3-20 entfernen.');
}

// --- Verbotene Praktik nach Art. 5 (seit 22.10.2026) ------------------------
// Gate 2 muss die Stories mit anderer Bauweise pruefen, bevor etwas an BC4 geht
if (String(audit?.vorpruefung?.ai_act_klasse || '').toLowerCase() === 'unacceptable') {
  const andere = (audit.pflichten || []).filter(p => p.massnahme === 'andere_bauweise').map(p => p.id);
  weich.push(`Verbotene Praktik nach Art. 5 laut BC3-30${andere.length ? ` (Pflichten ${andere.join(', ')})` : ''}: `
    + 'Stories mit anderer Bauweise vor der Freigabe an Gate 2 prüfen.');
}

if (f.length) {
  // EINE Zeile: n8n reicht dem Orchestrator nur die erste Zeile einer
  // Fehlermeldung weiter. Mit Zeilenumbruechen kam bei R6 und im Protokoll
  // bis zum 12.10.2026 nur die Kopfzeile an, ohne einen einzigen Verstoss.
  throw new Error(
    `Ausgangspruefung fehlgeschlagen — ${f.length} Verstoss/Verstöße gegen tickets.schema.json (${V}). ` +
    `Es wurde nichts hochgeladen. Verstöße: ` + f.join(' | ')
  );
}

// Ergebnis der Prüfung ins Audit schreiben, damit es die Lieferung begleitet
const stats = $('Umschlag auspacken').first().json.pruefung_vollstaendigkeit || {};
if (audit) {
  audit.pruefung_bc3 = {
    geprueft_gegen: `tickets.schema.json ${V}`,
    ergebnis: 'bestanden',
    befunde: weich,
    epics: (tickets.epics || []).length,
    stories: (tickets.epics || []).reduce((s, e) => s + (e.stories || []).length, 0),
    ...stats,
    // Nach ...stats: stats bringt die Befunde aus BC3-20 mit und hat bis zum
    // 12.10.2026 die eigenen weichen Befunde von BC3-40 still ueberschrieben.
    befunde: [...(stats.befunde || []), ...weich],
  };
}

return items;

const items = $input.all().map(i => i.json);
const rein = $('Vom Orchestrator aufgerufen').first().json;
const u = rein.umschlag || {};
const tickets = items.find(x => x._datei === 'tickets');
const audit = items.find(x => x._datei !== 'tickets');

return [{
  json: {
    lauf_id: tickets?.lieferung_id || rein.lauf_id,
    umschlag: {
      ...u,
      // Kennung und Kurzname gehören in den Umschlag, nicht nur in die Dateien.
      // Alle Stufen dahinter - Ordnername, Dateinamen, Repo-Pfad - hängen daran.
      lieferung: {
        ...(u.lieferung || {}),
        dateien: items,
        lieferung_id: tickets?.lieferung_id || null,
        projekt_kurzname: tickets?.projekt_kurzname || null,
      },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-40 Tickets bauen und prüfen',
        zeitpunkt: new Date().toISOString(),
        status: 'ok',
        umfang: {
          schema_version: tickets?.schema_version,
          epics: (tickets?.epics || []).length,
          stories: (tickets?.epics || []).reduce((s, e) => s + (e.stories || []).length, 0),
        },
        // Seit 23.10.2026 (C9): zuerst die Zuordnungen (Prüfen-Befunde, korrigierte
        // Verweise, nicht angehängte Doppel), dann die Befunde der Ausgangsprüfung
        befunde: [...(audit?.befunde_zuordnung || []), ...(audit?.pruefung_bc3?.befunde || [])],
      }],
    },
  },
}];

// Ohne lesbaren Compliance-Befund keine Lieferung: Einstufung und Pflichten fehlten sonst still
const items = $input.all();
const t = items.find(i => i.json._datei === 'tickets')?.json || {};
const audit = items.find(i => i.json._datei === 'compliance-audit')?.json || {};
const v = audit.vorpruefung || {};

const fehlt = [];
if (t._statistik?.compliance_parse_fehler) fehlt.push(`Antwort unlesbar (${t._statistik.compliance_parse_fehler})`);
if (!v.ai_act_klasse) fehlt.push('ai_act_klasse');
if (!v.ampel) fehlt.push('ampel');
if (!Array.isArray(audit.pflichten)) fehlt.push('pflichten');

// Text „Prüfung fehlgeschlagen“ nicht ändern, BC3-99 erkennt daran die Art
if (fehlt.length) {
  throw new Error(`Prüfung fehlgeschlagen: Compliance-Befund aus BC3-30 fehlt oder ist unvollständig (${fehlt.join(', ')}), nichts geliefert (BC3-40)`);
}
return items;
